-- 059. Эксперты: запасные реакции под озвучку (проверка voice-checker 25.11): без сокращений, «уже», «все», «потом»,
-- время словами. Только текст; audio_url сохраняется.
begin;
update characters set reaction_rules = (select jsonb_agg(case when r->>'id' = 'R126' then jsonb_set(r, '{text}', to_jsonb('"Кан смотрит выписку поверх очков. Откладывает.\n— Угорел… Это райотдел так решил, голубчик. Без вскрытия ни я, ни они этого не знаем. Тело у меня в журнале с прочерком. Направьте — посмотрю."'::json #>> '{}')) else r end) from jsonb_array_elements(reaction_rules) r) where id = 'a6c62ec0-5ff9-53a5-b9a2-20898741074b';
update characters set reaction_rules = (select jsonb_agg(case when r->>'id' = 'R131' then jsonb_set(r, '{text}', to_jsonb('"— Двадцать минут двенадцатого, говорите… Смерть по моему заключению около десяти вечера. Через час его могли везти. Могли и не везти. Это я по трупу не определю."'::json #>> '{}')) else r end) from jsonb_array_elements(reaction_rules) r) where id = 'a6c62ec0-5ff9-53a5-b9a2-20898741074b';
update characters set reaction_rules = (select jsonb_agg(case when r->>'id' = 'R132' then jsonb_set(r, '{text}', to_jsonb('"— Наркоз в десять минут двенадцатого? Это к анестезиологам, голубчик. Я скажу одно: умер он около десяти вечера. А где она была — это журналы, не морг."'::json #>> '{}')) else r end) from jsonb_array_elements(reaction_rules) r) where id = 'a6c62ec0-5ff9-53a5-b9a2-20898741074b';
update characters set reaction_rules = (select jsonb_agg(case when r->>'id' = 'R250' then jsonb_set(r, '{text}', to_jsonb('"— Следы на снегу — это к Гульнаре. Она по подошве скажет больше, чем я по пятке живого человека.\n(возвращает листок)\nЯ ногу вижу, когда она на столе."'::json #>> '{}')) else r end) from jsonb_array_elements(reaction_rules) r) where id = 'a6c62ec0-5ff9-53a5-b9a2-20898741074b';
update characters set reaction_rules = (select jsonb_agg(case when r->>'id' = 'R256' then jsonb_set(r, '{text}', to_jsonb('"— Журнал проходной. Кто вошёл, кто вышел.\n(перелистывает, не читая)\nУ меня свой журнал, голубчик: кто вошёл и больше не вышел. Ваш — не по моей части."'::json #>> '{}')) else r end) from jsonb_array_elements(reaction_rules) r) where id = 'a6c62ec0-5ff9-53a5-b9a2-20898741074b';
update characters set reaction_rules = (select jsonb_agg(case when r->>'id' = 'R257' then jsonb_set(r, '{text}', to_jsonb('"Кан держит ксерокопию на вытянутой руке.\n— Восемь портретов на листе, и на всех один человек. Это к Гульнаре, она купюры считает лучше кассира."'::json #>> '{}')) else r end) from jsonb_array_elements(reaction_rules) r) where id = 'a6c62ec0-5ff9-53a5-b9a2-20898741074b';
update characters set reaction_rules = (select jsonb_agg(case when r->>'id' = 'R259' then jsonb_set(r, '{text}', to_jsonb('"Кан читает протокол осмотра подвала. Долго. Снимает очки.\n— Матрас, ведро, верёвки. Двое суток, значит, там.\n(пауза)\nПро подвал — это Гульнара. А что он там пережил, я вам написал. Больше, чем написал, сказать не могу."'::json #>> '{}')) else r end) from jsonb_array_elements(reaction_rules) r) where id = 'a6c62ec0-5ff9-53a5-b9a2-20898741074b';
update characters set reaction_rules = (select jsonb_agg(case when r->>'id' = 'R263' then jsonb_set(r, '{text}', to_jsonb('"— Журнал общежития. Вахтёрши, поверьте старику, точнее любого хронометра.\n(возвращает)\nНо время смерти я вам назвал. Остальное — ваша арифметика."'::json #>> '{}')) else r end) from jsonb_array_elements(reaction_rules) r) where id = 'a6c62ec0-5ff9-53a5-b9a2-20898741074b';
update characters set reaction_rules = (select jsonb_agg(case when r->>'id' = 'R269' then jsonb_set(r, '{text}', to_jsonb('"— «Месяц тебе, или сядешь». Громко сказано.\n(пожимает плечами)\nЯ слышу только тех, кто больше ничего не кричит, голубчик. Это к вам."'::json #>> '{}')) else r end) from jsonb_array_elements(reaction_rules) r) where id = 'a6c62ec0-5ff9-53a5-b9a2-20898741074b';
update characters set reaction_rules = (select jsonb_agg(case when r->>'id' = 'R273' then jsonb_set(r, '{text}', to_jsonb('"— «Иди завскладом». Обидные слова.\n(протирает очки)\nНа моём веку от обидных слов умирали реже, чем говорят. Но это не наука, голубчик, это психология. К Бейсенову."'::json #>> '{}')) else r end) from jsonb_array_elements(reaction_rules) r) where id = 'a6c62ec0-5ff9-53a5-b9a2-20898741074b';
update characters set reaction_rules = (select jsonb_agg(case when r->>'id' = 'R276' then jsonb_set(r, '{text}', to_jsonb('"— Немец, уехал в Германию, а телефон остался.\n(вздыхает)\nУезжают, голубчик, один за другим. Мне сказать нечего, это к адресному бюро."'::json #>> '{}')) else r end) from jsonb_array_elements(reaction_rules) r) where id = 'a6c62ec0-5ff9-53a5-b9a2-20898741074b';
update characters set reaction_rules = (select jsonb_agg(case when r->>'id' = 'R286' then jsonb_set(r, '{text}', to_jsonb('"— Машины, цвет, фары.\n(отодвигает справку)\nЯ, голубчик, тридцать лет на автобусе. В машинах не понимаю. Это к Ринату."'::json #>> '{}')) else r end) from jsonb_array_elements(reaction_rules) r) where id = 'a6c62ec0-5ff9-53a5-b9a2-20898741074b';
update characters set reaction_rules = (select jsonb_agg(case when r->>'id' = 'R136' then jsonb_set(r, '{text}', to_jsonb('"— По протоколу угар. Машину райотдел не осматривал, только описал. Пока Кан не скажет, что не угар, смотреть её мне не на что."'::json #>> '{}')) else r end) from jsonb_array_elements(reaction_rules) r) where id = 'd3ddcd6d-4093-5464-970c-de4ad3cb9af1';
update characters set reaction_rules = (select jsonb_agg(case when r->>'id' = 'R137' then jsonb_set(r, '{text}', to_jsonb('"Сеитова читает акт до конца.\n— В машину посадили мёртвым. Значит, машину смотреть надо. Где она, на стоянке райотдела? Дайте их протокол."'::json #>> '{}')) else r end) from jsonb_array_elements(reaction_rules) r) where id = 'd3ddcd6d-4093-5464-970c-de4ad3cb9af1';
update characters set reaction_rules = (select jsonb_agg(case when r->>'id' = 'R142' then jsonb_set(r, '{text}', to_jsonb('"— По свежему снегу в ночь на воскресенье. С тех пор оттепель. Там каша, колею не снять. Не моя графа — только время."'::json #>> '{}')) else r end) from jsonb_array_elements(reaction_rules) r) where id = 'd3ddcd6d-4093-5464-970c-de4ad3cb9af1';
update characters set reaction_rules = (select jsonb_agg(case when r->>'id' = 'R143' then jsonb_set(r, '{text}', to_jsonb('"— Женские тридцать седьмого, под коркой слякоти. Дневные. Я так и записала. С её словами не спорят."'::json #>> '{}')) else r end) from jsonb_array_elements(reaction_rules) r) where id = 'd3ddcd6d-4093-5464-970c-de4ad3cb9af1';
update characters set reaction_rules = (select jsonb_agg(case when r->>'id' = 'R234' then jsonb_set(r, '{text}', to_jsonb('"— Горный Гигант. Глина в арках как раз такая. Грунт со двора Шмидтов — под навесом — возьму, сравню. Двор вы видели."'::json #>> '{}')) else r end) from jsonb_array_elements(reaction_rules) r) where id = 'd3ddcd6d-4093-5464-970c-de4ad3cb9af1';
update characters set reaction_rules = (select jsonb_agg(case when r->>'id' = 'R314' then jsonb_set(r, '{text}', to_jsonb('"— Свет отключали с семи вечера до двух ночи.\n(записывает в блокнот)\nДля осмотра в темноте нужен фонарь. Для экспертизы — ничего. Справка не моя."'::json #>> '{}')) else r end) from jsonb_array_elements(reaction_rules) r) where id = 'd3ddcd6d-4093-5464-970c-de4ad3cb9af1';
update characters set reaction_rules = (select jsonb_agg(case when r->>'id' = 'R319' then jsonb_set(r, '{text}', to_jsonb('"Сеитова узнаёт протокол сравнения.\n— Мой протокол. Тридцать купюр, каждая есть в копиях.\n(возвращает)\nПодпись моя. Повторять не буду."'::json #>> '{}')) else r end) from jsonb_array_elements(reaction_rules) r) where id = 'd3ddcd6d-4093-5464-970c-de4ad3cb9af1';
update characters set reaction_rules = (select jsonb_agg(case when r->>'id' = 'R324' then jsonb_set(r, '{text}', to_jsonb('"— Моё сравнение. Пять купюр из конверта, пять из пяти есть в копиях.\n(без выражения)\nУстановлено. Подпись моя."'::json #>> '{}')) else r end) from jsonb_array_elements(reaction_rules) r) where id = 'd3ddcd6d-4093-5464-970c-de4ad3cb9af1';
update characters set reaction_rules = (select jsonb_agg(case when r->>'id' = 'R327' then jsonb_set(r, '{text}', to_jsonb('"— Справка от гаишников.\n(откладывает)\nЦвет машины — не след. Краску с места я не изымала. Не моя графа."'::json #>> '{}')) else r end) from jsonb_array_elements(reaction_rules) r) where id = 'd3ddcd6d-4093-5464-970c-de4ad3cb9af1';
update characters set reaction_rules = (select jsonb_agg(case when r->>'id' = 'R149' then jsonb_set(r, '{text}', to_jsonb('"Абишев вздыхает.\n— Белая двадцать четвёртая, одна фара. Номера нет. Белых «Волг» у гаишников по городу — тысячи. Фару в учёт не пишут. Будут фамилии — проверю, на ком какая машина."'::json #>> '{}')) else r end) from jsonb_array_elements(reaction_rules) r) where id = '14e9bc6d-22f0-5005-b51c-e0678d8fa225';
update characters set reaction_rules = (select jsonb_agg(case when r->>'id' = 'R151' then jsonb_set(r, '{text}', to_jsonb('"— Журнал дежурств — больничный. Там всё подтверждено, с подписью. Мне по моим учётам проверять нечего."'::json #>> '{}')) else r end) from jsonb_array_elements(reaction_rules) r) where id = '14e9bc6d-22f0-5005-b51c-e0678d8fa225';
update characters set reaction_rules = (select jsonb_agg(case when r->>'id' = 'R154' then jsonb_set(r, '{text}', to_jsonb('"— Судимость девяносто четвёртого — в картотеке есть, подтвердится. Только что он сидел, вы и так знаете. Под что запрос? Нужен вопрос: телефон, адрес, машина."'::json #>> '{}')) else r end) from jsonb_array_elements(reaction_rules) r) where id = '14e9bc6d-22f0-5005-b51c-e0678d8fa225';
update characters set reaction_rules = (select jsonb_agg(case when r->>'id' = 'R156' then jsonb_set(r, '{text}', to_jsonb('"— Звонок был с таксофона. Через телефонную станцию такой не поднимешь. Таксофон он и есть таксофон. По этим словам запрос делать не по чему."'::json #>> '{}')) else r end) from jsonb_array_elements(reaction_rules) r) where id = '14e9bc6d-22f0-5005-b51c-e0678d8fa225';
update characters set reaction_rules = (select jsonb_agg(case when r->>'id' = 'R159' then jsonb_set(r, '{text}', to_jsonb('"— Чья «девятка», и так ясно. Где она ночью стояла, гаишники не пишут. Проверять тут по учётам нечего."'::json #>> '{}')) else r end) from jsonb_array_elements(reaction_rules) r) where id = '14e9bc6d-22f0-5005-b51c-e0678d8fa225';
update characters set reaction_rules = (select jsonb_agg(case when r->>'id' = 'R163' then jsonb_set(r, '{text}', to_jsonb('"— Горный Гигант — это сотни дворов, улицы без названий. Без точного адреса запрос не сделать."'::json #>> '{}')) else r end) from jsonb_array_elements(reaction_rules) r) where id = '14e9bc6d-22f0-5005-b51c-e0678d8fa225';
update characters set reaction_rules = (select jsonb_agg(case when r->>'id' = 'R174' then jsonb_set(r, '{text}', to_jsonb('"— Четвёртый пункт мой: данные гаишников по машинам. Остальное — Сеитова и Кан.\n(постукивает ручкой по строчке)\nМоё там всё верно. Вывод сами."'::json #>> '{}')) else r end) from jsonb_array_elements(reaction_rules) r) where id = '14e9bc6d-22f0-5005-b51c-e0678d8fa225';
update characters set reaction_rules = (select jsonb_agg(case when r->>'id' = 'R334' then jsonb_set(r, '{text}', to_jsonb('"Абишев читает журнал морга и морщится.\n— «Для хранения до выдачи родственникам». Красиво райотдел умеет не работать.\n(возвращает)\nЭто к Юрию Николаевичу, я в морг без нужды не спускаюсь. Там холодно, и он смеётся."'::json #>> '{}')) else r end) from jsonb_array_elements(reaction_rules) r) where id = '14e9bc6d-22f0-5005-b51c-e0678d8fa225';
update characters set reaction_rules = (select jsonb_agg(case when r->>'id' = 'R338' then jsonb_set(r, '{text}', to_jsonb('"Абишев смотрит на купюры, не трогая.\n— Пять бумажек по сто долларов. Моя зарплата за… а, неважно, за долго.\n(отодвигает)\nПо номерам купюр учёта у нас нет. Это к Гуле, у неё лупа лучше."'::json #>> '{}')) else r end) from jsonb_array_elements(reaction_rules) r) where id = '14e9bc6d-22f0-5005-b51c-e0678d8fa225';
update characters set reaction_rules = (select jsonb_agg(case when r->>'id' = 'R340' then jsonb_set(r, '{text}', to_jsonb('"Абишев с интересом листает журнал КПП.\n— Амбарная книга. Красота. Вот так бы каждый учёт вёл, мне бы работы на полдня меньше.\n(возвращает)\nНо это готовые записи. Запрашивать по ним нечего, всё перед вами."'::json #>> '{}')) else r end) from jsonb_array_elements(reaction_rules) r) where id = '14e9bc6d-22f0-5005-b51c-e0678d8fa225';
update characters set reaction_rules = (select jsonb_agg(case when r->>'id' = 'R345' then jsonb_set(r, '{text}', to_jsonb('"Абишев смотрит на бумажку под диском.\n— «48-27-15». Знакомый номер.\n(откладывает)\nЯ его поднимал. Чей — в справке. Больше по аппарату ничего не скажу."'::json #>> '{}')) else r end) from jsonb_array_elements(reaction_rules) r) where id = '14e9bc6d-22f0-5005-b51c-e0678d8fa225';
update characters set reaction_rules = (select jsonb_agg(case when r->>'id' = 'R347' then jsonb_set(r, '{text}', to_jsonb('"Абишев листает выписку из журнала вахты.\n— Вахтёрши — лучшая картотека в городе. Ни один компьютер так не запомнит, кто во сколько пришёл.\n(возвращает)\nТут мне добавить нечего, всё записано."'::json #>> '{}')) else r end) from jsonb_array_elements(reaction_rules) r) where id = '14e9bc6d-22f0-5005-b51c-e0678d8fa225';
update characters set reaction_rules = (select jsonb_agg(case when r->>'id' = 'R353' then jsonb_set(r, '{text}', to_jsonb('"— Моя справка. Электросети Кок-Тобе.\n(вздыхает)\nДиспетчер без печати не отдавал, пришлось ехать. Свет не горел с семи вечера до двух ночи. Это справка, не обвинение. Вывод сами."'::json #>> '{}')) else r end) from jsonb_array_elements(reaction_rules) r) where id = '14e9bc6d-22f0-5005-b51c-e0678d8fa225';
update characters set reaction_rules = (select jsonb_agg(case when r->>'id' = 'R356' then jsonb_set(r, '{text}', to_jsonb('"Абишев узнаёт свою справку.\n— Моя. Ручное сравнение: одну карту искал полдня, зато дальше сверил быстро.\n(с гордостью)\nКомпьютер, между прочим, так не умеет. Всё, что было в картотеке, там. Вывод сами."'::json #>> '{}')) else r end) from jsonb_array_elements(reaction_rules) r) where id = '14e9bc6d-22f0-5005-b51c-e0678d8fa225';
update characters set reaction_rules = (select jsonb_agg(case when r->>'id' = 'R357' then jsonb_set(r, '{text}', to_jsonb('"— Моя выписка. Журнал оператора.\n(усмехается)\nДевочки в пейджинговой меня по голосу узнают. «ЧЕТВЕРГ В СИЛЕ? Ф.» — как написано, так и переписал. Вывод сами."'::json #>> '{}')) else r end) from jsonb_array_elements(reaction_rules) r) where id = '14e9bc6d-22f0-5005-b51c-e0678d8fa225';
update characters set reaction_rules = (select jsonb_agg(case when r->>'id' = 'R365' then jsonb_set(r, '{text}', to_jsonb('"Абишев узнаёт свою справку из ГАИ.\n— Моя. Информационный центр и гаишники, два окна, два дня.\n(перечисляет по пальцам)\nБелые — у двоих. Остальные — нет. Это справка, не обвинение. Вывод сами."'::json #>> '{}')) else r end) from jsonb_array_elements(reaction_rules) r) where id = '14e9bc6d-22f0-5005-b51c-e0678d8fa225';
update characters set reaction_rules = (select jsonb_agg(case when r->>'id' = 'R366' then jsonb_set(r, '{text}', to_jsonb('"Абишев читает санкцию.\n— Прокурор подписал. Быстро, кстати. Обычно неделю ходим.\n(возвращает)\nЗадержание — это оперативники. Мне запросить нечего."'::json #>> '{}')) else r end) from jsonb_array_elements(reaction_rules) r) where id = '14e9bc6d-22f0-5005-b51c-e0678d8fa225';
update characters set reaction_rules = (select jsonb_agg(case when r->>'id' = 'R367' then jsonb_set(r, '{text}', to_jsonb('"— Моя справка. Учётное дело девяносто четвёртого, анкета, графа «родственники».\n(постукивает по листу)\nДальше адресное бюро, прописка по общагам. Три ящика перебрал. Что нашёл — то и написал. Вывод сами."'::json #>> '{}')) else r end) from jsonb_array_elements(reaction_rules) r) where id = '14e9bc6d-22f0-5005-b51c-e0678d8fa225';
update characters set reaction_rules = (select jsonb_agg(case when r->>'id' = 'R172' then jsonb_set(r, '{text}', to_jsonb('"— А это показания против конкретного лица. Здесь моя работа закончена. Имён я не называю."'::json #>> '{}')) else r end) from jsonb_array_elements(reaction_rules) r) where id = '11b90ca2-3c48-573f-95ac-041cf0635f90';
update characters set reaction_rules = (select jsonb_agg(case when r->>'id' = 'R369' then jsonb_set(r, '{text}', to_jsonb('"Бейсенов читает журнал морга. Постукивает карандашом по прочерку.\n— Позвольте заметить: это не ошибка, это система. Районы экономят на экспертизе, когда версия удобна.\n(возвращает)\nНо это наблюдение о райотделе, не о деле. По существу — к Юрию Николаевичу."'::json #>> '{}')) else r end) from jsonb_array_elements(reaction_rules) r) where id = '11b90ca2-3c48-573f-95ac-041cf0635f90';
update characters set reaction_rules = (select jsonb_agg(case when r->>'id' = 'R378' then jsonb_set(r, '{text}', to_jsonb('"— Ксерокопии купюр.\n(с уважением)\nКто-то в этой истории мыслит как бухгалтер: снял копии на всякий случай. Это говорит о недоверии. К кому — это ваш вопрос."'::json #>> '{}')) else r end) from jsonb_array_elements(reaction_rules) r) where id = '11b90ca2-3c48-573f-95ac-041cf0635f90';
update characters set reaction_rules = (select jsonb_agg(case when r->>'id' = 'R382' then jsonb_set(r, '{text}', to_jsonb('"— Телефон в пустом доме.\n(задумчиво)\nПустой дом — классика. Хозяева далеко, соседи привыкли не смотреть. Для профиля это пока только декорация."'::json #>> '{}')) else r end) from jsonb_array_elements(reaction_rules) r) where id = '11b90ca2-3c48-573f-95ac-041cf0635f90';
update characters set reaction_rules = (select jsonb_agg(case when r->>'id' = 'R385' then jsonb_set(r, '{text}', to_jsonb('"— Ботинки.\n(не берёт)\nОбувь — это предметное доказательство. Не моя область. Сопоставление проведёт криминалист."'::json #>> '{}')) else r end) from jsonb_array_elements(reaction_rules) r) where id = '11b90ca2-3c48-573f-95ac-041cf0635f90';
update characters set reaction_rules = (select jsonb_agg(case when r->>'id' = 'R390' then jsonb_set(r, '{text}', to_jsonb('"— Бывшая жена была на Кок-Тобе днём.\n(откладывает)\nБывшие супруги — классический круг подозрения. Именно поэтому, как правило, их проверяют первыми и именно поэтому ошибаются чаще всего. Решайте по фактам."'::json #>> '{}')) else r end) from jsonb_array_elements(reaction_rules) r) where id = '11b90ca2-3c48-573f-95ac-041cf0635f90';
update characters set reaction_rules = (select jsonb_agg(case when r->>'id' = 'R396' then jsonb_set(r, '{text}', to_jsonb('"— Телефон эмигранта.\n(задумчиво)\nНемцы уезжают, жильё пустеет. Социальное явление, между прочим, у меня об этом статья есть.\n(спохватывается)\nК делу: пустой дом как место — показателен. Кто его знал — ваш вопрос."'::json #>> '{}')) else r end) from jsonb_array_elements(reaction_rules) r) where id = '11b90ca2-3c48-573f-95ac-041cf0635f90';
update characters set reaction_rules = (select jsonb_agg(case when r->>'id' = 'R399' then jsonb_set(r, '{text}', to_jsonb('"— «ЧЕТВЕРГ В СИЛЕ? Ф.».\n(перечитывает)\nТелеграфный стиль, подпись одной буквой. Так пишут люди, которые договорились заранее. Кто такой «Ф.» — не мой вопрос."'::json #>> '{}')) else r end) from jsonb_array_elements(reaction_rules) r) where id = '11b90ca2-3c48-573f-95ac-041cf0635f90';
update characters set reaction_rules = (select jsonb_agg(case when r->>'id' = 'R402' then jsonb_set(r, '{text}', to_jsonb('"— Обувь совпала со следами.\n(откладывает)\nЭто не криминология, это криминалистика. Факт сильный. Мне добавить нечего."'::json #>> '{}')) else r end) from jsonb_array_elements(reaction_rules) r) where id = '11b90ca2-3c48-573f-95ac-041cf0635f90';
update characters set reaction_rules = (select jsonb_agg(case when r->>'id' = 'R411' then jsonb_set(r, '{text}', to_jsonb('"— Сводная справка по экспертизам.\n(читает внимательно)\nОтсев. Это хорошая работа ваших коллег. Профиль от этого сужается. Мне добавить нечего."'::json #>> '{}')) else r end) from jsonb_array_elements(reaction_rules) r) where id = '11b90ca2-3c48-573f-95ac-041cf0635f90';
commit;
